import React, { useEffect, useState } from 'react';
import styled from 'styled-components';

interface LoaderContainerProps {
  isExiting: boolean;
}

const LoaderContainer = styled.div<LoaderContainerProps>`
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  background: ${props => props.theme.colors.background};
  z-index: 1000;
  opacity: ${props => props.isExiting ? 0 : 1};
  transition: opacity 0.3s ease;
`;

const LoaderImage = styled.img`
  width: 150px;
  height: 150px;
  object-fit: contain;
`;

export const Loader: React.FC = () => {
  const [isExiting, setIsExiting] = useState(false);

  useEffect(() => {
    const handleBeforeUnmount = () => {
      setIsExiting(true);
    };

    // This mimics an exit animation without using framer-motion
    return () => {
      handleBeforeUnmount();
    };
  }, []);

  return (
    <LoaderContainer isExiting={isExiting}>
      <LoaderImage 
        src="/images/electrivire.gif" 
        alt="Loading..."
      />
    </LoaderContainer>
  );
}; 